package com.dtm.platform.service;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.dtm.platform.entity.*;import com.dtm.platform.repository.*;import com.dtm.platform.dto.*;import com.dtm.platform.exception.*;import org.springframework.http.HttpStatus;import org.springframework.data.domain.*;import java.util.*;
@Service public class ContactService {
 private final ContactMessageRepository contacts;private final AnalyticsEventRepository events;public ContactService(ContactMessageRepository contacts,AnalyticsEventRepository events){this.contacts=contacts;this.events=events;}
 @Transactional public Map<String,Object> submit(ContactInput input){if(input.website()!=null&&!input.website().isBlank())return Map.of("status","received");if(input.submissionKey()!=null){var found=contacts.findBySubmissionKey(input.submissionKey());if(found.isPresent())return Map.of("id",found.get().id,"status","received");}var c=new ContactMessage();c.name=input.name();c.email=input.email();c.phone=input.phone();c.company=input.company();c.projectType=input.projectType();c.budget=input.budget();c.message=input.message();c.submissionKey=input.submissionKey();contacts.saveAndFlush(c);return Map.of("id",c.id,"status","received");}
 @Transactional(readOnly=true) public PageDto<ContactMessage> list(String q,String status,int page,int size){org.springframework.data.jpa.domain.Specification<ContactMessage> spec=(root,query,cb)->{var ps=new ArrayList<jakarta.persistence.criteria.Predicate>();if(status!=null&&!status.isBlank())ps.add(cb.equal(root.get("status"),status));if(q!=null&&!q.isBlank()){String term="%"+q.toLowerCase(Locale.ROOT)+"%";ps.add(cb.or(cb.like(cb.lower(root.get("name")),term),cb.like(cb.lower(root.get("email")),term)));}return cb.and(ps.toArray(jakarta.persistence.criteria.Predicate[]::new));};var out=contacts.findAll(spec,PageRequest.of(Math.max(0,page),Math.max(1,Math.min(100,size)),Sort.by(Sort.Direction.DESC,"createdAt")));return new PageDto<>(out.getContent(),out.getTotalElements(),out.getNumber(),out.getSize(),out.getTotalPages());}
 @Transactional public ContactMessage update(long id,String status,Long version){if(!Set.of("NEW","CONTACTED","IN_PROGRESS","CONVERTED","CLOSED").contains(status))throw new IllegalArgumentException("Unknown lead status");var row=contacts.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Contact not found."));if(!Objects.equals(version,row.version))throw new ApiException(HttpStatus.CONFLICT,"Contact changed. Reload before updating.");row.status=status;return contacts.saveAndFlush(row);}
@Transactional public void delete(long id){var c=contacts.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Contact not found."));contacts.delete(c);}
}